package com.acme.notify.rendering;

import java.util.Map;

/**
 * Renders a template with recipient data, rejecting missing placeholders.
 */
public class TemplateRenderer {

    private final TemplateRepository templates;

    public TemplateRenderer(TemplateRepository templates) {
        this.templates = templates;
    }

    public RenderedMessage render(String templateId, String recipientEmail, Map<String, String> model) {
        EmailTemplate t = templates.require(templateId);
        for (String placeholder : t.getRequiredPlaceholders()) {
            if (!model.containsKey(placeholder)) {
                throw new MissingPlaceholderException(templateId, placeholder);
            }
        }
        String subject = substitute(t.getSubject(), model);
        String body = substitute(t.getBody(), model);
        return new RenderedMessage(recipientEmail, subject, body);
    }

    private String substitute(String source, Map<String, String> model) {
        String result = source;
        for (Map.Entry<String, String> e : model.entrySet()) {
            result = result.replace("${ " + e.getKey() + " }", e.getValue());
        }
        return result;
    }
}

