package com.acme.notify.rendering;

/** Validates that an email template compiles without syntax errors. */
public class TemplateValidator {
    public void validate(EmailTemplate t) {
        int open = count(t.getBody(), "${");
        int close = count(t.getBody(), "}");
        if (open != close) {
            throw new IllegalArgumentException("Unbalanced placeholders in " + t.getId());
        }
    }

    private int count(String s, String token) {
        int c = 0, i = 0;
        while ((i = s.indexOf(token, i)) >= 0) { c++; i += token.length(); }
        return c;
    }
}

