package com.acme.notify.campaigns;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Queues a campaign to a deduplicated recipient list.
 */
@RestController
public class CampaignSendController {

    private final TemplateRenderer renderer;
    private final OutboundQueue queue;

    public CampaignSendController(TemplateRenderer renderer, OutboundQueue queue) {
        this.renderer = renderer;
        this.queue = queue;
    }

    @PostMapping("/campaigns/send")
    public CampaignSendResult send(@RequestBody CampaignSendRequest req) {
        Set<String> seen = new HashSet<>();
        int queued = 0;
        for (Recipient r : req.getRecipients()) {
            if (!seen.add(r.getEmail().toLowerCase())) {
                continue;
            }
            RenderedMessage msg = renderer.render(req.getTemplateId(), r.getEmail(), r.getModel());
            queue.enqueue(msg);
            queued++;
        }
        return new CampaignSendResult(req.getCampaignId(), queued);
    }
}

