package com.acme.notify.delivery;

import java.time.Duration;
import java.time.Instant;

/**
 * Retries failed deliveries with exponential backoff, capped at five attempts.
 */
public class RetryPolicy {

    private static final int MAX_ATTEMPTS = 5;
    private static final Duration BASE_DELAY = Duration.ofMinutes(1);

    public boolean shouldRetry(DeliveryAttempt attempt) {
        return attempt.getAttemptCount() < MAX_ATTEMPTS && !attempt.isPermanentFailure();
    }

    public Instant nextAttemptAt(DeliveryAttempt attempt, Instant now) {
        long backoff = BASE_DELAY.toMillis() * (1L << Math.max(0, attempt.getAttemptCount() - 1));
        return now.plusMillis(backoff);
    }

    public void markPermanentIfExhausted(DeliveryAttempt attempt) {
        if (attempt.getAttemptCount() >= MAX_ATTEMPTS) {
            attempt.markPermanentFailure("Retries exhausted");
        }
    }
}

