/**
 * Enforces one-recipient-per-message for bulk sends, avoiding address exposure.
 */
public class NoSharedRecipientsRule {

    public void assertSingleRecipient(List<RenderedMessage> messages) {
        for (RenderedMessage m : messages) {
            int recipients = m.getTo().size() + (m.getCc() == null ? 0 : m.getCc().size());
            if (recipients > 1) {
                throw new SharedRecipientsException(m.getTo());
            }
        }
    }
}

