package com.acme.notify.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists a delivery record for each outbound notification.
 */
public class NotificationLogWriter {

    private final EntityManager em;

    public NotificationLogWriter(EntityManager em) {
        this.em = em;
    }

    public void record(String recipient, String templateId, String channel, String providerResponse) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            NotificationLogEntry e = new NotificationLogEntry();
            e.setRecipient(recipient);
            e.setTemplateId(templateId);
            e.setChannel(channel);
            e.setProviderResponse(providerResponse);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

