    char email[320];
    int processed = 0;

    while (fgets(email, sizeof(email), in)) {
        trim_newline(email);
        if (email[0] == 0) continue;
        if (db_mark_undeliverable(email) != DB_OK) continue;
        db_remove_from_marketing_lists(email);
        processed++;
    }
    fclose(in);
    return processed;
}

